import * as THREE from './assets/three.module.js';
import {motionAt,clamp} from './motion.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
let paused=reduced.matches, scenes=[],last=performance.now(),heroTime=0;
const visible=new Set();
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)visible.add(e.target);else visible.delete(e.target);if(e.target.tagName==='VIDEO'){if(e.isIntersecting){if(!e.target.src){e.target.src=e.target.dataset.src;e.target.load();}if(!paused&&!e.target.dataset.userPaused)e.target.play().catch(()=>{});}else e.target.pause();}}),{rootMargin:'0px',threshold:.08});
function syncPause(){document.body.classList.toggle('motion-paused',paused);$('#motion-toggle').setAttribute('aria-pressed',String(paused));$('#motion-toggle').innerHTML=paused?'Resume motion <span aria-hidden="true">▶</span>':'Pause motion <span aria-hidden="true">Ⅱ</span>';$$('video').forEach(v=>{if(paused)v.pause();else if(visible.has(v)&&!v.dataset.userPaused)v.play().catch(()=>{});});}
$('#motion-toggle').addEventListener('click',()=>{paused=!paused;syncPause();});reduced.addEventListener('change',()=>{paused=reduced.matches;syncPause();});syncPause();
$$('video').forEach(v=>{observer.observe(v);v.addEventListener('pause',()=>{if(!paused&&visible.has(v)&&!document.hidden)v.dataset.userPaused='1';});v.addEventListener('play',()=>{delete v.dataset.userPaused;});});
$$('.film-play').forEach(button=>button.addEventListener('click',()=>{const host=button.closest('.film');const iframe=document.createElement('iframe');iframe.src=`https://www.youtube-nocookie.com/embed/${host.dataset.videoId}?autoplay=1&rel=0`;iframe.title=button.getAttribute('aria-label');iframe.allow='autoplay; encrypted-media; picture-in-picture; fullscreen';iframe.allowFullscreen=true;iframe.referrerPolicy='strict-origin-when-cross-origin';host.replaceChildren(iframe);}));
$$('.contents a').forEach(a=>a.addEventListener('click',()=>$('.contents').open=false));document.addEventListener('click',e=>{if(!e.target.closest('.contents'))$('.contents').open=false;});document.addEventListener('keydown',e=>{if(e.key==='Escape')$('.contents').open=false;});
const sections=$$('.tracked');let scrollPending=false;
function updateReading(){scrollPending=false;const max=document.documentElement.scrollHeight-innerHeight;$('#reading-progress').style.width=`${max?scrollY/max*100:0}%`;let current=sections[0];for(const section of sections){if(section.getBoundingClientRect().top<=innerHeight*.45)current=section;else break;}$('#current-chapter').textContent=current.dataset.chapter||'The course';}
addEventListener('scroll',()=>{if(!scrollPending){scrollPending=true;requestAnimationFrame(updateReading)}},{passive:true});addEventListener('resize',updateReading);updateReading();
const reveals=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.remove('waiting');reveals.unobserve(e.target);}}),{threshold:.05});
if(!reduced.matches)$$('.lesson h2,.lesson .lead,.spec-grid,.prompt').forEach(el=>{el.classList.add('reveal-ready');if(el.getBoundingClientRect().top>innerHeight)el.classList.add('waiting');reveals.observe(el);});
function setupScene(host,scale=6){const canvas=host.querySelector('canvas');const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;const scene=new THREE.Scene();const camera=new THREE.OrthographicCamera(-scale,scale,scale,-scale,.1,80);camera.position.set(7,9,10);camera.lookAt(0,0,0);scene.add(new THREE.HemisphereLight(0xffffff,0xb7aa96,3));const key=new THREE.DirectionalLight(0xfff2dd,4.5);key.position.set(-4,10,5);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.camera.left=-9;key.shadow.camera.right=9;key.shadow.camera.top=9;key.shadow.camera.bottom=-9;key.shadow.normalBias=.03;key.shadow.bias=-.0002;key.shadow.radius=4;scene.add(key);const fill=new THREE.DirectionalLight(0xffffff,1.5);fill.position.set(6,4,-5);scene.add(fill);const floor=new THREE.Mesh(new THREE.PlaneGeometry(200,200),new THREE.ShadowMaterial({color:0x453e34,opacity:.15}));floor.rotation.x=-Math.PI/2;floor.position.y=-.04;floor.receiveShadow=true;scene.add(floor);const resize=()=>{const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h,false);camera.left=-scale*w/h;camera.right=scale*w/h;camera.top=scale;camera.bottom=-scale;camera.updateProjectionMatrix();};new ResizeObserver(resize).observe(host);resize();host.classList.add('ready');observer.observe(host);canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();host.classList.remove('ready');});canvas.addEventListener('webglcontextrestored',()=>{host.classList.add('ready');resize();});return{host,scene,camera,renderer};}
function material(color){return new THREE.MeshStandardMaterial({color,roughness:.36,metalness:.12});}
function roundedCube(size,mat){const r=.075,s=size/2-r;const shape=new THREE.Shape();shape.moveTo(-s,-s);shape.lineTo(s,-s);shape.lineTo(s,s);shape.lineTo(-s,s);shape.closePath();const geo=new THREE.ExtrudeGeometry(shape,{depth:size-2*r,bevelEnabled:true,bevelSegments:3,steps:1,bevelSize:r,bevelThickness:r});geo.center();const mesh=new THREE.Mesh(geo,mat);mesh.castShadow=true;mesh.receiveShadow=true;return mesh;}
try{const s=setupScene($('#hero-scene'),4.4);const group=new THREE.Group();s.scene.add(group);const black=material(0x333536),cream=material(0xd4cec2),orange=material(0xff5a22);const objects=[];for(let i=0;i<6;i++){const angle=i/6*Math.PI*2;const obj=i%2===0?roundedCube(1.04,black):new THREE.Mesh(new THREE.CylinderGeometry(.51,.51,.97,48),cream);obj.position.set(Math.cos(angle)*2.7,.53,Math.sin(angle)*2.7);obj.castShadow=true;obj.receiveShadow=true;group.add(obj);objects.push(obj);}const path=new THREE.EllipseCurve(0,0,2.7,2.7,0,2*Math.PI,false,0);const points=path.getPoints(120).map(p=>new THREE.Vector3(p.x,.035,p.y));const line=new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineBasicMaterial({color:0xc6baaa}));group.add(line);const pulse=new THREE.Mesh(new THREE.SphereGeometry(.24,32,24),orange);pulse.castShadow=true;group.add(pulse);const trail=[];for(let i=0;i<22;i++){const dot=new THREE.Mesh(new THREE.SphereGeometry(.055*(1-i/25),12,8),new THREE.MeshBasicMaterial({color:0xff7840,transparent:true,opacity:(1-i/22)*.7}));group.add(dot);trail.push(dot);}let drag=false,px=0,rotation=0;const canvas=s.renderer.domElement;canvas.addEventListener('pointerdown',e=>{drag=true;px=e.clientX;canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(drag){rotation+=(e.clientX-px)*.008;px=e.clientX;}});canvas.addEventListener('pointerup',()=>drag=false);canvas.addEventListener('pointercancel',()=>drag=false);s.update=dt=>{if(!paused)heroTime=(heroTime+dt)%10;const a=heroTime/10*Math.PI*2;group.rotation.y+=(rotation-group.rotation.y)*.12;pulse.position.set(Math.cos(a)*2.7,.38,Math.sin(a)*2.7);trail.forEach((p,i)=>p.position.set(Math.cos(a-i*.025)*2.7,.12,Math.sin(a-i*.025)*2.7));objects.forEach((obj,i)=>{const lag=((a-i/6*Math.PI*2)%(Math.PI*2)+Math.PI*2)%(Math.PI*2);const bounce=lag<.9?Math.sin(lag/.9*Math.PI)*.42:0;obj.position.y=.53+bounce;obj.rotation.z=i%2===0?bounce*.18:0;});$('#loop-time').textContent=heroTime.toFixed(1).padStart(4,'0');$('#relay-progress').style.width=heroTime*10+'%';};scenes.push(s);}catch(e){console.warn('3D preview unavailable; showing the course illustration.',e);$('.drag-hint').textContent='Kinetic Relay · course illustration';}
function frame(now){const dt=Math.min((now-last)/1000,.05);last=now;if(!document.hidden)for(const s of scenes){if(visible.has(s.host)){s.update(dt);s.renderer.render(s.scene,s.camera);}}requestAnimationFrame(frame);}requestAnimationFrame(frame);
// LAB_IMPLEMENTATION
function lightMotionStudio(study){
 const {scene,renderer}=study;
 scene.background=new THREE.Color(0x8c8195);
 scene.fog=new THREE.Fog(0x8c8195,12,29);
 renderer.toneMappingExposure=1.05;
 scene.traverse(object=>{
  if(object.isHemisphereLight){object.color.set(0xf4e5ee);object.groundColor.set(0x57485e);object.intensity=.85;}
  if(object.isDirectionalLight){
   if(object.castShadow){object.position.set(-3,6,4);object.color.set(0xffe0ce);object.intensity=3.2;object.shadow.camera.left=-5;object.shadow.camera.right=5;object.shadow.camera.top=5;object.shadow.camera.bottom=-5;object.shadow.camera.updateProjectionMatrix();object.shadow.normalBias=.015;object.shadow.radius=4;}
   else{object.position.set(4,3,-3);object.color.set(0xcfc7ff);object.intensity=1.7;}
  }
  if(object.isMesh&&object.material.isShadowMaterial){object.material.dispose();object.material=new THREE.MeshStandardMaterial({color:0xb9a4ac,roughness:.82,metalness:0});}
 });
 const wash=new THREE.SpotLight(0xffbfa9,65,22,.85,.95,1.5);
 wash.position.set(-1,5,-3);wash.target.position.set(0,0,-2);scene.add(wash,wash.target);
 // Broad studio panels provide reflections without extra runtime shadow maps.
 const room=new THREE.Scene();
 room.add(new THREE.Mesh(new THREE.BoxGeometry(24,18,24),new THREE.MeshBasicMaterial({color:0x796f83,side:THREE.BackSide})));
 for(const [x,y,z,w,h,power] of [[-4,5,3,3,7,3],[5,3,1,2,6,2],[0,6,-4,6,2,2]]){
  const panel=new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({color:new THREE.Color(power,power*.92,power*.87),side:THREE.DoubleSide}));
  panel.position.set(x,y,z);panel.lookAt(0,0,0);room.add(panel);
 }
 const generator=new THREE.PMREMGenerator(renderer);
 const environment=generator.fromScene(room,.06,.1,40);
 scene.environment=environment.texture;
 generator.dispose();room.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});
}
const descriptions={linear:'Equal distance every frame. The speed stays constant, giving the object a mechanical feeling.',ease:'Slow at the start, fast in the middle, soft at the end. The same distance feels more deliberate.',anticipation:'A small pullback prepares the eye before the main action. Notice how the beginning explains what comes next.',overshoot:'The object passes its destination, then settles back. A little extra distance makes its momentum visible.',heavy:'A slow start builds into a firm arrival with almost no bounce. The response suggests more weight.',playful:'A lifted arc, squash and stretch, and a generous overshoot make the same object feel flexible and lively.'};
let mode='ease',duration=2,labTime=0,labPaused=reduced.matches,labScene;
function refreshCurve(){let d='';for(let i=0;i<=100;i++){const t=i/100;d+=`${i?'L':'M'}${15+t*270},${85-motionAt(mode,t)*70}`;}$('#motion-curve').setAttribute('d',d);}
function updateLabUI(){const t=clamp(labTime/duration);$('#scrub').value=String(t*1000);$('#lab-time').value=`${(t*duration).toFixed(1)} s`;$('#curve-dot').setAttribute('cx',String(15+t*270));$('#curve-dot').setAttribute('cy',String(85-motionAt(mode,t)*70));$('#lab-play').textContent=labPaused||paused?'Play':'Pause';$('#lab-play').setAttribute('aria-pressed',String(labPaused||paused));}
if($('#lab-scene')){
 try{labScene=setupScene($('#lab-scene'),2.55);lightMotionStudio(labScene);labScene.camera.position.set(0,5,10);labScene.camera.lookAt(0,0,0);const main=new THREE.Mesh(new THREE.SphereGeometry(.38,40,28),new THREE.MeshPhysicalMaterial({color:0xff502c,metalness:.38,roughness:.23,clearcoat:1,clearcoatRoughness:.17,envMapIntensity:.8}));const reference=new THREE.Mesh(new THREE.SphereGeometry(.22,24,16),new THREE.MeshPhysicalMaterial({color:0x99958d,metalness:.15,roughness:.3,clearcoat:.5,envMapIntensity:.65}));main.castShadow=true;reference.castShadow=true;labScene.scene.add(main,reference);for(const z of [-.85,1.1]){const geometry=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-2.2,.005,z),new THREE.Vector3(2.2,.005,z)]);labScene.scene.add(new THREE.Line(geometry,new THREE.LineBasicMaterial({color:0x99818e,transparent:true,opacity:.55})));for(const x of [-2.2,2.2]){const ring=new THREE.Mesh(new THREE.RingGeometry(.4,.415,48),new THREE.MeshBasicMaterial({color:0x806573,side:THREE.DoubleSide,transparent:true,opacity:.8}));ring.rotation.x=-Math.PI/2;ring.position.set(x,.012,z);labScene.scene.add(ring);}}labScene.update=dt=>{if(!paused&&!labPaused)labTime=(labTime+dt)%(duration+.65);const t=clamp(labTime/duration),p=motionAt(mode,t);main.position.set(-2.2+4.4*p,.39,-.85);main.scale.setScalar(1);main.rotation.z=-p*Math.PI*2;if(mode==='playful'){const lift=Math.sin(t*Math.PI)*.75;const stretch=1+Math.sin(t*Math.PI*2)*.2;main.scale.set(1/Math.sqrt(stretch),stretch,1/Math.sqrt(stretch));main.position.y=.39*stretch+lift;}reference.position.set(-2.2+4.4*t,.23,1.1);updateLabUI();};scenes.push(labScene);}catch(e){console.warn('Motion study 3D is unavailable.',e);$('#lab-description').textContent='The live 3D view is unavailable on this device. The curve below still shows how each movement changes over time, and the course comparisons above remain playable.';}
 $$('input[name="motion-mode"]').forEach(input=>input.addEventListener('change',()=>{mode=input.value;labTime=0;$('#lab-description').textContent=descriptions[mode];$('#study-label').textContent=input.nextElementSibling.textContent;refreshCurve();updateLabUI();}));
 $('#duration').addEventListener('input',e=>{const t=labTime/duration;duration=Number(e.target.value);labTime=t*duration;$('#duration-value').value=duration.toFixed(1)+' s';updateLabUI();});
 $('#scrub').addEventListener('input',e=>{labPaused=true;labTime=Number(e.target.value)/1000*duration;updateLabUI();});
 $('#lab-play').addEventListener('click',()=>{if(labPaused||paused){labPaused=false;paused=false;syncPause();}else labPaused=true;if(labTime>=duration)labTime=0;updateLabUI();});refreshCurve();updateLabUI();
 if(!labScene){observer.observe($('#lab-scene'));scenes.push({host:$('#lab-scene'),update:dt=>{if(!paused&&!labPaused)labTime=(labTime+dt)%(duration+.65);updateLabUI();},renderer:{render(){}},scene:null,camera:null});}
}
